def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or ''
    tt = nb.get('task_type') or text(getv(ctx, 'task.task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested target type. Do not place a substitute; recover by setting it aside if needed and finding the exact target.'
    elif stage == 'take_target' and target:
        msg = 'A requested target type is available here. Take the exact target instead of a different object type.'
    elif stage == 'transform' and target and verb:
        place = 'sinkbasin'
        if verb == 'heat':
            place = 'microwave'
        if verb == 'cool':
            place = 'fridge'
        msg = 'Before final placement, ' + verb + ' the ' + target + ' using the ' + place + '. Do not put it at the destination yet.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are holding the correct target. Put the ' + target + ' in/on the ' + dest + ' now; do not use a different receptacle.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' for final placement; avoid extra examine, look, or inventory actions.'
    elif 'two' in tt and nb.get('placed_count', 0) > 0 and stage in ('find_target', 'take_target'):
        msg = 'One target is already placed. Leave it there, find another ' + target + ', and use the same destination type.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

