def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', nb.get('task_type', '')))
    target = text(getv(ctx, 'task.target_type', nb.get('target_type', '')))
    dest = text(getv(ctx, 'task.destination_type', nb.get('destination_type', '')))
    verb = needverb(tt)
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act or not target:
        return None
    inv = text(getv(ctx, 'world.inventory', ''))
    holding_target = bool(target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong_inv = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and not holding_target)
    if wrong_inv and act.startswith('put ') and target not in act:
        return {'kind': 'block_and_prompt', 'message': 'This would place a non-target object. Keep searching for the exact requested target type instead.'}
    if verb and not nb.get('transformed') and act.startswith('put ') and target in act and dest and dest in act:
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target at the destination yet. First perform the required ' + verb + ' step, then return to the destination.'}
    if 'two' in tt and act.startswith('take ') and target in act and nb.get('placed_count', 0) > 0:
        locs = text(getv(ctx, 'world.placed_locations', nb.get('placed_locations', '')))
        if locs and locs in act:
            return {'kind': 'block_and_prompt', 'message': 'Do not take back an already placed target. Find another target of the same type and use the same destination.'}
    return None
